CREATE DATABASE IF NOT EXISTS wiki_ecommerce CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE wiki_ecommerce;
SET default_storage_engine=InnoDB;
CREATE TABLE roles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(40) NOT NULL UNIQUE);
CREATE TABLE permissions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE);
CREATE TABLE role_permissions (role_id BIGINT UNSIGNED NOT NULL, permission_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(role_id,permission_id), FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE, FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE);
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, role_id BIGINT UNSIGNED NOT NULL DEFAULT 1, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, phone VARCHAR(30), verified_at DATETIME NULL, session_version INT NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE user_addresses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, label VARCHAR(60) NOT NULL, address TEXT NOT NULL, city VARCHAR(100) NOT NULL, province VARCHAR(100) NOT NULL, country VARCHAR(80) NOT NULL, postal_code VARCHAR(20) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE password_resets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at DATETIME NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE email_verifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, parent_id BIGINT UNSIGNED NULL, name VARCHAR(100) NOT NULL, slug VARCHAR(120) NOT NULL UNIQUE, FOREIGN KEY(parent_id) REFERENCES categories(id) ON DELETE RESTRICT);
CREATE TABLE products (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, category_id BIGINT UNSIGNED NOT NULL, name VARCHAR(180) NOT NULL, slug VARCHAR(190) NOT NULL UNIQUE, sku VARCHAR(80) NOT NULL UNIQUE, brand VARCHAR(80) NOT NULL DEFAULT 'WIKI', type ENUM('clothing','scents') NOT NULL, short_description VARCHAR(500) NOT NULL, description TEXT NOT NULL, price INT UNSIGNED NOT NULL, sale_price INT UNSIGNED NULL, cost_price INT UNSIGNED NOT NULL DEFAULT 0, status ENUM('active','draft','archived') NOT NULL DEFAULT 'active', featured BOOLEAN NOT NULL DEFAULT 0, fragrance_family VARCHAR(80), top_notes VARCHAR(255), middle_notes VARCHAR(255), base_notes VARCHAR(255), gender VARCHAR(40), longevity VARCHAR(80), concentration VARCHAR(80), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(category_id) REFERENCES categories(id), INDEX catalog(status,type,created_at), INDEX category_status(category_id,status), CHECK (sale_price IS NULL OR sale_price <= price));
CREATE TABLE product_images (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, product_id BIGINT UNSIGNED NOT NULL, path VARCHAR(255) NOT NULL, alt VARCHAR(255) NOT NULL, position INT NOT NULL DEFAULT 0, FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE product_variants (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, product_id BIGINT UNSIGNED NOT NULL, sku VARCHAR(100) NOT NULL UNIQUE, size VARCHAR(20) NOT NULL DEFAULT '', color VARCHAR(40) NOT NULL DEFAULT '', volume VARCHAR(20) NOT NULL DEFAULT '', price_adjustment INT NOT NULL DEFAULT 0, FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE, UNIQUE variant_combination(product_id,size,color,volume));
CREATE TABLE inventory (variant_id BIGINT UNSIGNED PRIMARY KEY, stock INT UNSIGNED NOT NULL DEFAULT 0, minimum_stock INT UNSIGNED NOT NULL DEFAULT 5, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(variant_id) REFERENCES product_variants(id) ON DELETE CASCADE);
CREATE TABLE wishlists (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL UNIQUE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE wishlist_items (wishlist_id BIGINT UNSIGNED NOT NULL, product_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(wishlist_id,product_id), FOREIGN KEY(wishlist_id) REFERENCES wishlists(id) ON DELETE CASCADE, FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE coupons (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, type ENUM('percentage','fixed') NOT NULL, value INT UNSIGNED NOT NULL, minimum_amount INT UNSIGNED NOT NULL DEFAULT 0, maximum_discount INT UNSIGNED NULL, starts_at DATETIME NOT NULL, expires_at DATETIME NOT NULL, usage_limit INT UNSIGNED NOT NULL DEFAULT 100, per_user_limit INT UNSIGNED NOT NULL DEFAULT 1, used_count INT UNSIGNED NOT NULL DEFAULT 0, active BOOLEAN NOT NULL DEFAULT 1, CHECK(type <> 'percentage' OR value <= 100));
CREATE TABLE orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, number VARCHAR(40) NOT NULL UNIQUE, user_id BIGINT UNSIGNED NULL, guest_token_hash CHAR(64) NOT NULL, checkout_key CHAR(64) NOT NULL UNIQUE, email VARCHAR(190) NOT NULL, customer_name VARCHAR(120) NOT NULL, phone VARCHAR(30) NOT NULL, shipping_address JSON NOT NULL, billing_address JSON NOT NULL, notes TEXT, shipping_method VARCHAR(40) NOT NULL, subtotal INT UNSIGNED NOT NULL, discount INT UNSIGNED NOT NULL, shipping INT UNSIGNED NOT NULL, tax INT UNSIGNED NOT NULL, total INT UNSIGNED NOT NULL, coupon_id BIGINT UNSIGNED NULL, status ENUM('pending','confirmed','processing','shipped','out_for_delivery','delivered','cancelled','returned','refunded') NOT NULL DEFAULT 'confirmed', payment_status ENUM('pending','paid','failed','refunded','partially_refunded') NOT NULL DEFAULT 'pending', stock_restored BOOLEAN NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL, FOREIGN KEY(coupon_id) REFERENCES coupons(id) ON DELETE SET NULL, INDEX customer_orders(user_id,created_at), INDEX reporting(created_at,status));
CREATE TABLE order_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, product_id BIGINT UNSIGNED NOT NULL, variant_id BIGINT UNSIGNED NOT NULL, name VARCHAR(180) NOT NULL, sku VARCHAR(100) NOT NULL, variant VARCHAR(120) NOT NULL, quantity INT UNSIGNED NOT NULL, unit_price INT UNSIGNED NOT NULL, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE, FOREIGN KEY(product_id) REFERENCES products(id), FOREIGN KEY(variant_id) REFERENCES product_variants(id));
CREATE TABLE coupon_usage (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, coupon_id BIGINT UNSIGNED NOT NULL, order_id BIGINT UNSIGNED NOT NULL UNIQUE, identity_hash CHAR(64) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(coupon_id) REFERENCES coupons(id), FOREIGN KEY(order_id) REFERENCES orders(id), INDEX usage_identity(coupon_id,identity_hash));
CREATE TABLE payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, provider VARCHAR(40) NOT NULL, reference VARCHAR(190) NULL UNIQUE, amount INT UNSIGNED NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'pending', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE shipments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL UNIQUE, carrier VARCHAR(100) NOT NULL, tracking_number VARCHAR(120) NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE returns (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL UNIQUE, user_id BIGINT UNSIGNED NULL, reason TEXT NOT NULL, status ENUM('requested','approved','rejected','received') NOT NULL DEFAULT 'requested', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE refunds (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, amount INT UNSIGNED NOT NULL, reference VARCHAR(190) NOT NULL UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE reviews (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, product_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, rating TINYINT UNSIGNED NOT NULL, body TEXT NOT NULL, status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending', verified BOOLEAN NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(product_id) REFERENCES products(id), FOREIGN KEY(user_id) REFERENCES users(id), UNIQUE one_review(product_id,user_id), CHECK(rating BETWEEN 1 AND 5));
CREATE TABLE newsletter_subscribers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, email VARCHAR(190) NOT NULL UNIQUE, active BOOLEAN NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE banners (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(190) NOT NULL, body VARCHAR(500) NOT NULL, url VARCHAR(190) NOT NULL DEFAULT '/shop', active BOOLEAN NOT NULL DEFAULT 1);
CREATE TABLE notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, kind VARCHAR(40) NOT NULL, message VARCHAR(500) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE login_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, identity_hash CHAR(64) NOT NULL, success BOOLEAN NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX throttle(identity_hash,created_at));
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NULL, action VARCHAR(100) NOT NULL, context JSON NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE site_settings (name VARCHAR(100) PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE email_outbox (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, recipient VARCHAR(190) NOT NULL, subject VARCHAR(190) NOT NULL, body TEXT NOT NULL, status ENUM('queued','sending','sent','failed') NOT NULL DEFAULT 'queued', attempts INT NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE analytics_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, session_hash CHAR(64) NOT NULL, event VARCHAR(40) NOT NULL, detail VARCHAR(190) NOT NULL DEFAULT '', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX event_time(event,created_at));
INSERT INTO roles(id,name) VALUES(1,'customer'),(2,'administrator'),(3,'fulfillment');
INSERT INTO permissions(name) VALUES('catalog.manage'),('orders.manage'),('marketing.manage'),('reports.view'),('users.manage'),('settings.manage');
INSERT INTO role_permissions SELECT 2,id FROM permissions;
INSERT INTO role_permissions SELECT 3,id FROM permissions WHERE name IN ('orders.manage','reports.view');
